body:
![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

When multiple concurrent API requests are initiated while the access token is expired or missing, they will all independently trigger a token refresh request (`refreshTokens()`). Under standard Refresh Token Rotation (RTR), exchanging the same refresh token multiple times concurrently will trigger reuse detection on the backend, leading to immediate session revocation and unexpected user logouts.

To prevent this race condition, we should deduplicate concurrent refresh requests by sharing a single active refresh promise across all concurrent invocations of `authorizedFetch`.

```javascript
    async authorizedFetch(input, init = {}) {
      async function fetchWithToken(accessToken) {
        return fetchImpl(input, {
          ...init,
          headers: {
            ...(init.headers || {}),
            Authorization: 'Bearer ' + accessToken,
          },
        });
      }

      let accessToken = getStoredBackendAccessToken({ storage });
      if (!accessToken) {
        if (!client._refreshPromise) {
          client._refreshPromise = refreshTokens().finally(() => {
            client._refreshPromise = null;
          });
        }
        const refreshed = await client._refreshPromise;
        if (!refreshed) throw createMissingSessionError();
        accessToken = getStoredBackendAccessToken({ storage });
      }

      let response = await fetchWithToken(accessToken);
      if (response.status !== 401) return response;

      if (!client._refreshPromise) {
        client._refreshPromise = refreshTokens().finally(() => {
          client._refreshPromise = null;
        });
      }
      const refreshed = await client._refreshPromise;
      if (!refreshed) return response;

      accessToken = getStoredBackendAccessToken({ storage });
      response = await fetchWithToken(accessToken);
      if (response.status === 401) {
        clear_tokens: clearBackendAuthTokens({ storage });
        notifySessionInvalidated();
      }
      return response;
    },
